// Credentials Demo — exercises anna.credentials.* (HOST API) and
// anna.tools.invoke → credentials/* (Reverse RPC via bundled Executa).
//
// Loaded as a native ES module; imports the Anna App Runtime SDK directly.

import { AnnaAppRuntime } from "/static/anna-apps/_sdk/latest/index.js";

// Resolve the executa tool_id at runtime. `anna-tool-ids.js` (generated by
// `anna-app dev` / `apps publish`) assigns `window.__ANNA_TOOL_IDS__`; the
// string literal is only a fallback for mock/offline runs.
const EXECUTA_HANDLE = "credentials-via-executa";
const EXECUTA_TOOL_ID =
  (typeof window !== "undefined" &&
    window.__ANNA_TOOL_IDS__ &&
    window.__ANNA_TOOL_IDS__[EXECUTA_HANDLE]) ||
  "tool-test-credentials-via-executa-12345678";

const TRANSPORT_HINTS = {
  host:
    "Calls anna.credentials.list_accounts / get_token directly from the iframe. " +
    "Gated by manifest ui.host_api.credentials + the per-app 'Connected accounts' " +
    "permission (credentials_grant).",
  executa:
    "Invokes the bundled Executa, which issues credentials/listAccounts + " +
    "credentials/getToken reverse-RPCs. Gated by the Executa manifest's " +
    "credentials declaration (GOOGLE_ACCESS_TOKEN → provider 'google'). " +
    "Not served by mock fixtures — use `anna-app dev` against a real host.",
};

const $ = (id) => document.getElementById(id);
const errBox = $("errors");

// Gmail content (senders, subjects, snippets) is untrusted — always escape
// before innerHTML.
function esc(s) {
  return String(s ?? "").replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])
  );
}

function showError(e) {
  errBox.classList.remove("hidden");
  errBox.textContent = `${new Date().toLocaleTimeString()} — ${e?.message || e}`;
  console.error(e);
}

function show(el, data) {
  el.textContent = typeof data === "string" ? data : JSON.stringify(data, null, 2);
}

function transport() {
  return $("transport").value;
}

function provider() {
  return ($("provider").value || "google").trim();
}

function updateHint() {
  $("transport-hint").textContent = TRANSPORT_HINTS[transport()];
}

// ── Executa path helper: unwrap tools.invoke → {success, tool, data} ──
async function invokeExecuta(anna, method, args) {
  const res = await anna.tools.invoke({
    tool_id: EXECUTA_TOOL_ID,
    method,
    args,
  });
  // The dispatcher unwraps the plugin's invoke envelope; depending on host
  // version the payload may be at res.data or res directly.
  return res?.data ?? res;
}

async function listAccounts(anna) {
  if (transport() === "host") {
    return anna.credentials.list_accounts({ provider: provider() });
  }
  return invokeExecuta(anna, "list_accounts", { provider: provider() });
}

async function getToken(anna, accountId) {
  if (transport() === "host") {
    const out = await anna.credentials.get_token({
      provider: provider(),
      account_id: accountId || null,
    });
    // HOST API returns the raw token — mask it in the UI (never render or
    // persist full tokens in a demo surface).
    const tok = out?.access_token || "";
    return {
      provider: provider(),
      account_id: out?.account_id,
      expires_at: out?.expires_at,
      token_prefix: tok ? tok.slice(0, 8) + "…" : "",
      token_length: tok.length,
    };
  }
  // Reverse RPC path: the plugin masks server-side (token_info).
  return invokeExecuta(anna, "token_info", {
    provider: provider(),
    account: accountId || "",
  });
}

// ── Gmail (token consumer) ─────────────────────────────────────────

const GMAIL_API = "https://gmail.googleapis.com/gmail/v1/users/me";

async function gmailGet(token, path, params) {
  const qs = params ? "?" + new URLSearchParams(params).toString() : "";
  const resp = await fetch(GMAIL_API + path + qs, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!resp.ok) {
    const body = (await resp.text()).slice(0, 300);
    const hint =
      resp.status === 401 || resp.status === 403
        ? " (missing gmail.readonly scope on this account's authorization?)"
        : "";
    throw new Error(`Gmail API ${resp.status} on ${path}${hint}: ${body}`);
  }
  return resp.json();
}

function gmailMax() {
  const n = parseInt($("gmail-max").value, 10);
  return Number.isFinite(n) ? Math.min(10, Math.max(1, n)) : 5;
}

async function fetchGmail(anna, accountId) {
  const n = gmailMax();
  if (transport() === "host") {
    // HOST API: get a short-lived token in the iframe, call Gmail directly.
    // gmail.googleapis.com is allowed via ui.bundle.external_origins
    // (auto-added to the bundle CSP's connect-src).
    const tok = await anna.credentials.get_token({
      provider: "google",
      account_id: accountId || null,
    });
    const token = tok?.access_token || "";
    const listing = await gmailGet(token, "/messages", { maxResults: n });
    const ids = (listing.messages || []).map((m) => m.id);
    const metas = await Promise.all(
      ids.map((id) =>
        // metadataHeaders repeats — use the array-of-pairs URLSearchParams form.
        gmailGet(token, `/messages/${id}`, [
          ["format", "metadata"],
          ["metadataHeaders", "From"],
          ["metadataHeaders", "Subject"],
          ["metadataHeaders", "Date"],
        ])
      )
    );
    const header = (meta, name) =>
      ((meta.payload?.headers || []).find(
        (h) => (h.name || "").toLowerCase() === name
      ) || {}).value || "";
    return {
      provider: "google",
      account_id: tok?.account_id,
      count: metas.length,
      messages: metas.map((meta) => ({
        id: meta.id,
        from: header(meta, "from"),
        subject: header(meta, "subject") || "(no subject)",
        date: header(meta, "date"),
        snippet: meta.snippet || "",
      })),
    };
  }
  // Reverse RPC path: the Executa exchanges the token and calls Gmail
  // server-side — the token never enters this iframe.
  return invokeExecuta(anna, "gmail_recent", {
    account: accountId || "",
    max_results: n,
  });
}

function renderMessages(out) {
  const box = $("gmail-list");
  const messages = out?.messages || [];
  if (!messages.length) {
    box.innerHTML = '<p class="muted">No messages returned.</p>';
    return;
  }
  box.innerHTML = messages
    .map(
      (m) => `
      <div class="mail-row">
        <div class="subject">${esc(m.subject)}</div>
        <div class="meta"><span>${esc(m.from)}</span><span>${esc(m.date)}</span></div>
        <div class="snippet">${esc(m.snippet)}</div>
      </div>`
    )
    .join("");
}

function renderAccounts(listing) {
  const box = $("accounts");
  const accounts = listing?.accounts || [];
  if (!accounts.length) {
    box.innerHTML =
      '<p class="muted">No authorized accounts — connect one on Settings → Authorizations.</p>';
    return;
  }
  box.innerHTML = accounts
    .map(
      (a) => `
      <div class="account-row" data-account-id="${a.account_id}">
        <span class="dot ${a.status === "active" ? "ok" : "bad"}"></span>
        <span class="email">${a.email || a.label || a.account_id}</span>
        ${a.is_default ? '<span class="badge">Default</span>' : ""}
        <button class="pick" data-account-id="${a.account_id}">Use</button>
      </div>`
    )
    .join("");
  box.querySelectorAll("button.pick").forEach((btn) => {
    btn.addEventListener("click", () => {
      $("account-id").value = btn.dataset.accountId;
    });
  });
}

// ── boot ─────────────────────────────────────────────────────────────

const anna = await AnnaAppRuntime.connect();
await anna.window.set_title({ title: "Credentials Demo" }).catch(() => {});

updateHint();
$("transport").addEventListener("change", updateHint);

$("btn-list").addEventListener("click", async () => {
  try {
    show($("list-out"), "…");
    const listing = await listAccounts(anna);
    renderAccounts(listing);
    show($("list-out"), listing);
  } catch (e) {
    show($("list-out"), "");
    showError(e);
  }
});

$("btn-token").addEventListener("click", async () => {
  try {
    show($("token-out"), "…");
    const info = await getToken(anna, ($("account-id").value || "").trim());
    show($("token-out"), info);
  } catch (e) {
    show($("token-out"), "");
    showError(e);
  }
});

$("btn-gmail").addEventListener("click", async () => {
  try {
    show($("gmail-out"), "…");
    $("gmail-list").innerHTML = "";
    const out = await fetchGmail(anna, ($("account-id").value || "").trim());
    renderMessages(out);
    // Keep the raw JSON visible but drop snippets to keep it compact.
    show($("gmail-out"), {
      ...out,
      messages: (out?.messages || []).map(({ snippet, ...m }) => m),
    });
  } catch (e) {
    show($("gmail-out"), "");
    showError(e);
  }
});

$("btn-injected").addEventListener("click", async () => {
  try {
    show($("injected-out"), "…");
    const info = await invokeExecuta(anna, "injected_credential_info", {});
    show($("injected-out"), info);
  } catch (e) {
    show($("injected-out"), "");
    showError(e);
  }
});
